--获取所有的事件
function RoleInstance:GetRoleAllEvents(roleId)
    roleId = checkNumber(self._roleId)
    if roleId <= 0 then
        return {}
    end
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting1811, roleId, nil, "AllEventIds")
    local _t = {}
    for k, v in pairs(t) do
        local vo = self:GetRoleEventVo(v) 
        if vo then
            if checkNumber(vo.type) ~= RoleEventType.Login then
                table.insert(_t, v)
            end
        end
    end

    --要开引导了
    if self:IsOpenSpecifyGuide() then
        --只有小白会
        if checkNumber(roleId) == GuideRoleId then
            local guideT = {}
            for k, v in pairs(_t) do
                local vo = self:GetRoleEventVo(v) 
                if vo then
                    --拿点击事件  只取一个
                    if checkNumber(vo.type) ~= RoleEventType.UIClick then
                        table.insert(guideT, v)
                        return guideT
                    end
                end
            end
        end
    end

    return _t
end

