function RoleInstance:OnUpdate()
    if isNull(self._ani) then
        return
    end

    self:UpDateTipsGo()
    --无事件
    if self._curRoleStatus == RoleStatus.None then
        --可以随事件
        if self:IsCanRandEvent() then
            local eventId = self:RandEventId()
            self:PlayEventById(eventId)
        end
    elseif self._curRoleStatus == RoleStatus.WaitIdle then
        self:WaitIdleStatus()
    elseif self._curRoleStatus == RoleStatus.EventPlaying then
        self:UpdateEvent()
    end

    if self._randEventTimeDown then
        self._randEventTimeDown = self._randEventTimeDown - CS.UnityEngine.Time.deltaTime
    end

    if self._destoryTime then
        self._destoryTime = self._destoryTime + CS.UnityEngine.Time.deltaTime
        if self._destoryTime >= self._destoryTargetTime then
            self._destoryTime = 0
            for k, v in pairs(self._destoryGoBuffer) do
                if not isNull(v) then
                    GameObject.Destroy(v)
                end
            end
        end
    end
end

--更新事件信息
function RoleInstance:UpdateEvent()
    if not self._curEventVo then
        return
    end

    local eventType = checkNumber(self._curEventVo.type)
    --到时间直接结束
    if self._isNeedWaitTrigger then
        self._waitTriggerTime = self._waitTriggerTime - CS.UnityEngine.Time.deltaTime
        if self._waitTriggerTime <= 0 then
            --直接到结束状态
            if eventType == RoleEventType.TLClick or eventType == RoleEventType.StoryClick or eventType == RoleEventType.Login then
                --如果没有触发才变
                if not self._isTriggerClick then
                    self:SetCurTimeLineStatus(TimeLineStatus.End)
                end
            else
                self:SetCurRoleStatus(RoleStatus.EventEnd)
            end
            self._isNeedWaitTrigger = false
            return
        end
    end

    --timeline 触发的事件
    if eventType == RoleEventType.StoryClick or eventType == RoleEventType.TLClick or eventType == RoleEventType.Login or eventType == RoleEventType.RoleLeave then
        --每个timeline都会走这个
        if self._curTLDurTime > 0 then
            self._curTLDurTime = self._curTLDurTime - CS.UnityEngine.Time.deltaTime
            if self._curTLDurTime <= 0 then
                self:SetCurRoleStatus(RoleStatus.EventEnd)
            end
        end
    elseif eventType == RoleEventType.RoleMove then 
        if self._curMoveStatus == MoveStatus.GetUp then
            if self._curTLDurTime > 0 then
                self._curTLDurTime = self._curTLDurTime - CS.UnityEngine.Time.deltaTime
                if self._curTLDurTime <= 0 then
                    self._curMoveStatus = MoveStatus.Moving
                end
            end
        --行走中
        elseif self._curMoveStatus == MoveStatus.Moving then
            local dis
            --正方向
            if self._normal >= 0 then
                dis = self._curMoveDis + self._moveSpeed * CS.UnityEngine.Time.deltaTime
                self._curMoveDis = dis
            else
                dis = self._curMoveDis - self._moveSpeed * CS.UnityEngine.Time.deltaTime
                self._curMoveDis = dis
            end
    
            local pos = self._wayCinemachineSmoothPath:StandardizeUnit(self._curMoveDis, 0)
            self._modelGo.transform.position = self._wayCinemachineSmoothPath:EvaluatePositionAtUnit(pos, 0)
    
            local rot = self._wayCinemachineSmoothPath:EvaluateOrientationAtUnit(pos, 0)
            --相反一下
            if self._normal < 0 then
                local rotAngle = CS.UnityEngine.Quaternion.AngleAxis(180, CS.UnityEngine.Vector3.up)
                rot = rot * rotAngle 
            end
            self._modelGo.transform.rotation = rot
    
            if self._normal >= 0 then
                if self._curMoveDis >= self._maxMoveDis then
                    self._curMoveStatus = MoveStatus.SitDown

                    self:RefreshCurTimeLineInfo()
                    self._curTLDurTime = self:GetCurTimeLineStatusDurTime(TimeLineStatus.Start)+2
                    self:PlayTimeLine()
                    self:SetAnimatorHomeInteger(0)
                end
            else
                if self._curMoveDis <= 0 then
                    self._curMoveStatus = MoveStatus.SitDown

                    self:RefreshCurTimeLineInfo()
                    self._curTLDurTime = self:GetCurTimeLineStatusDurTime(TimeLineStatus.Start)+2

                    self:PlayTimeLine()
                    self:SetAnimatorHomeInteger(0)
                end
            end
        elseif self._curMoveStatus == MoveStatus.SitDown then
            if self._curTLDurTime > 0 then
                self._curTLDurTime = self._curTLDurTime - CS.UnityEngine.Time.deltaTime
                if self._curTLDurTime <= 0 then
                    --更新下位置
                    self:RefreshPosId(self._targetPosId)
                    self:RefreshPosition()

                    self:SetCurRoleStatus(RoleStatus.EventEnd)
                end
            end
        end
    else
        
    end
end

--设置当前状态
function RoleInstance:SetCurRoleStatus(status)
    if status == RoleStatus.EventPlaying then
        --有些事件开始前要做些事情
        self:BeginEventShow()
    end

    self._curRoleStatus = status

    if status == RoleStatus.InitEvent then
        self:InitEventStatus()
    elseif status == RoleStatus.EventEnd then
        self:SetCurTipsGoActive(false)

        local eventType = checkNumber(self._curEventVo.type)
        if eventType == RoleEventType.StoryClick or eventType == RoleEventType.Login then 
            if not isNull(self._roleTalkGo) then
                GameObject.Destroy(self._roleTalkGo)
                if not isNull(self._roleTalkGoLoader) then
                    self._roleTalkGoLoader:Release(true)
                    self._roleTalkGoLoader = nil
                end
            end
            Events.Broadcast('AllMainUI', true)
            Events.Broadcast(Constants.EventNames.MainHomeScrollActive, {isTrue = true})
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("ClickMainHomeRole")
            KCookie.Set("MainHomeRoleEventPlay", 0)
            Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, { isTrue = true })

            KCookie.Set(Constants.IsOpnePageing, 0)
        end
        self:EndStatus()
    end
end

--随事件
function RoleInstance:RandEventId()
    --缓冲得
    local bufferId = self:GetBuffEventId()
    if bufferId then
        return bufferId
    end
    local isFirstStartGame = checkNumber(KCookie.Get('isFirstStartGame'))

    --小白强制引导了
    if self:IsOpenSpecifyGuide() and checkNumber(self._roleId) == GuideRoleId then

    elseif checkNumber(KCookie.Get('QTEShow')) == 1 or self._roleShowMgr._isHasQteShow then
        self._roleShowMgr._isHasQteShow = false
    else
        if checkInt(KCookie.Get(Constants.UICacheDataKeys.IS_PRE_DOWNLOAD)) == 1 then
            -- 好像只能用这一个动作，暂时先写死
            return '1080002'  -- Tips：一定不能用 1080004 小小白变身这个动作
        --第一次进游戏
        elseif isFirstStartGame == 0 then
            local eventId = self._roleShowMgr:GetEnterEventId(self._roleId)
            print('eventId 2', eventId)
            if checkNumber(eventId) > 0 then
                return eventId
            end
        --需要入场动作 取完就设置为false
        elseif self._isNeedEnterId then
            self:SetNeedEnterId(false)
            local eventId = self._roleShowMgr:GetEnterEventId(self._roleId)
            if checkNumber(eventId) > 0 then
                return eventId
            end
        end
    end

    local t 
    if self._lastEventVo then
        --上一个是离场 下一个必定是入场
        if checkNumber(self._lastEventVo.type) == RoleEventType.RoleLeave then
            local enterAniId = self._roleShowMgr:GetEnterEventId(self._roleId)
            if enterAniId then
                t = {enterAniId}
            end
        elseif not string.isEmpty(self._lastEventVo.endCall) then
            t = CfUtils.Split(self._lastEventVo.endCall)
        end
    else
        t = self:GetRoleAllEvents(self._roleId)
    end
    if not t then
        return nil
    end
    local num = math.random(#t)
    local eventId = t[num]
    return eventId
end

function RoleInstance:SetNeedEnterId(isTrue)
    self._isNeedEnterId = checkBool(isTrue)
end

--事件开始
function RoleInstance:PlayEventById(eventId)
    local vo = self:GetRoleEventVo(eventId)
    if not vo then
        return
    end
    self._curEventVo = vo

    self:SetCurRoleStatus(RoleStatus.InitEvent)
end 

function RoleInstance:InitEventStatus(eventId)
    local eventType = checkNumber(self._curEventVo.type)
    --有最长等待时间 超过时间直接结束
    if checkNumber(self._curEventVo.endTime) > 0 then
        self._waitTriggerTime = checkNumber(self._curEventVo.endTime)
        self._isNeedWaitTrigger = true
        self._isTriggerClick = false 
    end 

    if eventType == RoleEventType.StoryClick or eventType == RoleEventType.TLClick or eventType == RoleEventType.Login or eventType == RoleEventType.RoleLeave then
        self:InitAllTimeLineInfo(self._curEventVo.timelinePath)
    elseif eventType == RoleEventType.RoleMove then 
        self._targetPosId = self._roleShowMgr:GetFreePos()

        if self._targetPosId == 0 then
            return
        end
        local wayCinemachineSmoothPath, normal = self._roleShowMgr:GetWayCinemachineSmoothPath(self._posId, self._targetPosId)
        --没有找到路线  直接退出
        if isNull(wayCinemachineSmoothPath) then
            return
        end
        self._wayCinemachineSmoothPath = wayCinemachineSmoothPath
        self._maxMoveDis = wayCinemachineSmoothPath.m_Waypoints.Length - 1
        self._normal = normal
        if normal >= 0 then
            self._curMoveDis = 0
        else
            self._curMoveDis = self._maxMoveDis
        end
        self._moveSpeed = 0.1

        self._curMoveStatus = MoveStatus.None
    elseif eventType == RoleEventType.UIClick then 

    else

    end

    self:SetCurRoleStatus(RoleStatus.WaitIdle)
    self:RefreshTipsStatus()
end 

--要持续刷新朝向
function RoleInstance:UpDateTipsGo()
    if self._curEventVo then
        if not isNull(self._tipsParGo) then
            local type = self._curEventVo.bubbleBox
            local go = self._tipsParGo.transform:Find("tips"..type)
            if not isNull(go) then
                local mainCamera = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("Default"))
                if isNull(mainCamera) then
                    return
                end
                go.transform:LookAt(mainCamera.transform)
            end
        end
    end
end

--刷新提示的go
function RoleInstance:RefreshTipsStatus()
    if isNull(self._modelGo) then
        return
    end
    if isNull(self._curEventVo) then
        return
    end
    local type = self._curEventVo.bubbleBox
    if checkNumber(type) <= 0 then
        return
    end

    if isNull(self._tipsParGo) then
        self._tipsParGo = self._modelGo.transform:Find(TipsGoNode)
    end
    if isNull(self._tipsParGo) then
        return
    end

    local go = self._tipsParGo.transform:Find("tips"..type)
    if isNull(go) then
        local loader = self._roleShowMgr:GetTipsGoLoader(type)
        go = CfUtils.InstantiateGo(loader.ResultObject.gameObject, self._tipsParGo)
        go.name = "tips"..type
    end
    self:SetCurTipsGoActive(true)
end

function RoleInstance:SetCurTipsGoActive(isTrue)
    if isNull(self._parGo) then
        return
    end
    if isNull(self._curEventVo) then
        return
    end
    
    local type = self._curEventVo.bubbleBox
    if checkNumber(type) <= 0 then
        return
    end
    if isNull(self._tipsParGo) then
        self._tipsParGo = self._modelGo.transform:Find(TipsGoNode)
    end
    if isNull(self._tipsParGo) then
        return
    end

    --如果再打开ui界面  强行置false
    if KCookie.Get(Constants.IsBeginInteractive) == 1 then
        isTrue = false
    end

    local go = self._tipsParGo.transform:Find("tips"..type)
    KTool.SetActive(go, isTrue)
end

function RoleInstance:WaitIdleStatus()
    --如果事件为登录事件  不等动画播完直接切  解决第一次打开闪现变身问题
    if self._curEventVo then
        if checkNumber(self._curEventVo.type) == RoleEventType.Login then
            self:SetCurRoleStatus(RoleStatus.EventPlaying)
            return
        end
    end

    local animatorInfo = self._ani:GetCurrentAnimatorStateInfo(0)
    if animatorInfo then
        local animatorTime = animatorInfo.normalizedTime - math.floor(animatorInfo.normalizedTime)
        if animatorTime >= 0.9 then
            self:SetCurRoleStatus(RoleStatus.EventPlaying)
        end
    end
end

function RoleInstance:EndStatus()
    --清楚timeline loader
    if self._curEventVo then
        self._roleShowMgr:RemoveTimeLineLoader(self._curEventVo.timelinePath)
    end
    self._ani:Play("idle")  --纠正一下  防止动作衔接跳帧？
    --self:SetAnimatorHomeInteger(self:GetAnimatorNumByPosId(self._posId))

    --self._randEventTimeDown = 2
    self:ClearEventInfo()

    --离场播完换人
    if self._lastEventVo and checkNumber(self._lastEventVo.type) == RoleEventType.RoleLeave then
        self._roleShowMgr:ChangeRole(self._lastEventVo.roleId)
    else
        self:SetCurRoleStatus(RoleStatus.None)
    end
end

--开始事件表现
function RoleInstance:BeginEventShow()
    if not self._curEventVo then
        return
    end

    local eventType = checkNumber(self._curEventVo.type)

    --开始的时候timeline 调用的都走这里
    if eventType == RoleEventType.StoryClick or eventType == RoleEventType.Login then
        self:RefreshCurTimeLineInfo()
        self:PlayTimeLine()

        self:SetAnimatorHomeInteger(0)
    elseif eventType == RoleEventType.TLClick then
        self:RefreshCurTimeLineInfo()
        self:PlayTimeLine()

        self:SetAnimatorHomeInteger(0)
    elseif eventType == RoleEventType.RoleMove then 
        self:RefreshCurTimeLineInfo()

        self:PlayTimeLine()
        self:SetAnimatorHomeInteger(0)

        self._curTLDurTime = self:GetCurTimeLineStatusDurTime(TimeLineStatus.Start) +2 
        self._curMoveStatus = MoveStatus.GetUp
    elseif eventType == RoleEventType.RoleLeave then 
        self:RefreshCurTimeLineInfo()
        self:PlayTimeLine()

        self:SetAnimatorHomeInteger(0)

        if self._curTLInfo then
            self._curTLDurTime = checkNumber(self._curTLInfo.pdDurTime)
        else
            self._curTLDurTime = 0
        end
    else

    end
end

--刷新当前的timeline信息 取第一个出来刷新
function RoleInstance:RefreshCurTimeLineInfo()
    if not self._allTLInfo then
        return
    end
    --销毁上次的timeline信息
    if self._curTLInfo then
        if not isNull(self._curTLInfo.go) then
            GameObject.Destroy(self._curTLInfo.go)
        end
        self._curTLInfo = nil
    end

    self._curTLInfo = self._allTLInfo[1]
    table.remove(self._allTLInfo, 1)
end

--初始化所有的timeline信息
function RoleInstance:InitAllTimeLineInfo(path)
    if string.isEmpty(path) then
        return
    end

    local t = CfUtils.Split(path) 
    for k, v in pairs(t) do
        self:InitTimeLineByPath(v)
    end
end

--timeline信息
function RoleInstance:InitTimeLineByPath(path)
    if string.isEmpty(path) then
        return
    end
    local tlLoader = self._roleShowMgr:GetTimeLineLoader(path)
    if tlLoader then
        local go = CfUtils.InstantiateGo(tlLoader.ResultObject.gameObject, self._parGo)
        if go then
            --go.transform.localPosition = Vector3(0, 0, 0)   --zinan说的 不归0
            self:InitTimeLineSignal(go)
            self:NormalTimeLineInfo(go)
        end
    end
end

--需要有信号的地方
function RoleInstance:InitTimeLineSignal(go)
    if not go then
        return
    end

    local eventType = checkNumber(self._curEventVo.type)
    if eventType == RoleEventType.StoryClick or eventType == RoleEventType.TLClick or eventType == RoleEventType.Login then
        self:AddSignalReceiverComp(go, "Timeline/TimeLineSignal/HomeRoleIdle.signal", function()
            
        end)
        --判断是否能进入触发状态
        self:AddSignalReceiverComp(go, "Timeline/TimeLineSignal/HomeRoleTrigger.signal", function()
            --没点击触发  一直循环idle
            if not self._isTriggerClick then
                self:SetCurTimeLineStatus(TimeLineStatus.Idle)
            else

            end
        end)
        --timeline结束
        self:AddSignalReceiverComp(go, "Timeline/TimeLineSignal/HomeRoleEnd.signal", function()
            if not isNull(self._triggerCam) then
                CfUtils.SetActive(self._triggerCam, false)
            end

            Events.Broadcast(Constants.EventNames.CloseUIMainInteractionSkipDialog, {})   --抛出关闭界面得事件
            if self._curEventVo.ifEnd == 0 then
                self._curTLDurTime = 0.0000001   --直接结束
            else
                self._curTLDurTime = self:GetCurTimeLineStatusDurTime(TimeLineStatus.End) - 0.1
            end

            --self._curTLDurTime = 0.0000001   --直接结束
            CfUtils.ChangeMainCamDefalultBlend(1)
        end)
    elseif eventType == RoleEventType.RoleMove then 

    else

    end
end

--统一化timeline信息
function RoleInstance:NormalTimeLineInfo(go)
    if isNull(go) then
        return
    end
    print("timeline: "..go.name)
    local pd = KTool.GetComponent(go, typeof(CS.UnityEngine.Playables.PlayableDirector))
    if isNull(pd) then
        return
    end
    --没有资源 直接返回
    if isNull(pd.playableAsset) then
        return
    end
    
    local bindList = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    bindList:AddRange(pd.playableAsset.outputs)
    for i = 0, bindList.Count - 1 do
        local bind = bindList[i]
        --只设置人的节点
        if bind.streamName == "role" then
            pd:SetGenericBinding(bind.sourceObject, self._modelGo)

            local clipList = support.new_list(typeof(CS.UnityEngine.Timeline.TimelineClip))
            clipList:AddRange(bind.sourceObject:GetClips())
            local t = {}
            t.clipsTime = {}
            t.clipsDurTime = {}
            for i = 0, clipList.Count - 1 do
                t.clipsTime[clipList[i].displayName] = clipList[i].start
                t.clipsDurTime[clipList[i].displayName] = clipList[i].duration
            end
            t.go = go  
            t.pdDurTime = pd.duration
            print(table.dump(t))
            table.insert(self._allTLInfo, t)
        elseif bind.streamName == "triggerCamera" then
            self._triggerCam = pd:GetGenericBinding(bind.sourceObject)
        end
    end

    local markList = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    markList:AddRange(pd.playableAsset:GetRootTracks())
    self._curMarkerTimeInfo = {}
    for i = 0, markList.Count - 1 do
        local bind = markList[i]
        if bind.name == "Markers" then
            local count = bind:GetMarkerCount()
            for j = 0, count - 1 do
                local marker = bind:GetMarker(j)
                if not isNull(marker) and not isNull(marker.asset) then
                    if string.contains(marker.asset.name, MarkerKey.HomeRoleEnd) then
                        self._curMarkerTimeInfo[MarkerKey.HomeRoleEnd] = marker.time
                    elseif string.contains(marker.asset.name, MarkerKey.HomeRoleTrigger) then
                        self._curMarkerTimeInfo[MarkerKey.HomeRoleTrigger] = marker.time
                    elseif string.contains(marker.asset.name, MarkerKey.HomeRoleIdle) then
                        self._curMarkerTimeInfo[MarkerKey.HomeRoleIdle] = marker.time
                    end
                end
            end
        end
    end
    print(table.dump(self._curMarkerTimeInfo))

    pd:RebuildGraph()
    KTool.SetActive(go, false)
end

function RoleInstance:SetCurTimeLineStatus(type)
    local time = self:GetCurTimeLineStatusTime(type)
    if not isNull(self._curTLInfo) then
        local pd = KTool.GetComponent(self._curTLInfo.go, typeof(CS.UnityEngine.Playables.PlayableDirector))
        if isNull(pd) then
            return
        end
        pd:Pause()
        pd.time = time
        pd:Play()
    end
end

--用marker点的图标来设置时间
function RoleInstance:SetCurTimeLineMarkerStatus(type)
    local time = self:GetCurTimeLineMarkerStatusTime(type)
    local pd = KTool.GetComponent(self._curTLInfo.go, typeof(CS.UnityEngine.Playables.PlayableDirector))
    if isNull(pd) then
        return
    end
    pd:Pause()
    pd.time = time-0.01
    pd:Play()
end

function RoleInstance:GetCurTimeLineMarkerStatusTime(type)
    if not self._curMarkerTimeInfo then
        return 0
    end
    return checkNumber(self._curMarkerTimeInfo[type])
end

--获取当前timeline状态的开始时间
function RoleInstance:GetCurTimeLineStatusTime(type)
    if not self._curTLInfo then
        return 0
    end
    type = checkString(type)
    --trigger触发一次 打开相机
    if TimeLineStatus.Trigger == type then
        return checkNumber(self._curTLInfo.clipsTime[type])
    end
    return checkNumber(self._curTLInfo.clipsTime[type])
end

--获取当前timeline状态的持续时间
function RoleInstance:GetCurTimeLineStatusDurTime(type)
    if not self._curTLInfo then
        return 0
    end
    type = checkString(type)
    return checkNumber(self._curTLInfo.clipsDurTime[type])
end

--添加信号
function RoleInstance:AddSignalReceiverComp(go, signalPath, eventCb)
    if not go then
        return
    end

    local sr = KTool.GetOrAddComponent(go, typeof(SignalReceiver))
    ResourceModule.LoadBundleAsync(signalPath, function(loader, ok, resultObject)
        if ok then
            loader:Retain(sr)
            local event = CS.UnityEngine.Events.UnityEvent();
            event:AddListener(function()
                eventCb()
            end)
            sr:AddReaction(loader.ResultObject, event)
        end
        loader:Release()
    end)--"Timeline/Timeline.prefab"

    --if not loader.IsError then
    --    local event = CS.UnityEngine.Events.UnityEvent();
    --    event:AddListener(function()
    --        eventCb()
    --    end)
    --    sr:AddReaction(loader.ResultObject, event)
    --end

end

--清空一个timeline信息
--是否强制
function RoleInstance:ClearEventInfo(isForce)
    self:SetCurTipsGoActive(false)
    if self._curTLInfo then
        if not IsNull(self._curTLInfo.go) then
            --控制起直接强制删
            if isForce then 
                GameObject.Destroy(self._curTLInfo.go.gameObject)
            else
                --不播end的状态的这种要等摄像机融合完才能删
                if self._curEventVo.ifEnd == 0 then
                    KTool.SetActive(self._curTLInfo.go, false)
                    table.insert(self._destoryGoBuffer, self._curTLInfo.go.gameObject)
                    self._destoryTime = 0   --重置一次时间
                else
                    GameObject.Destroy(self._curTLInfo.go.gameObject)
                end
            end 
        end
    end
    self._triggerCam = nil
    self:RefreshAnimator()
    self._lastEventVo = self._curEventVo
    self._curEventVo = nil      
    self._curTLInfo = nil      
    self._allTLInfo = {}       
    self._curTLDurTime = 0   

    --timeline事件用的
    self._isNeedWaitTrigger = false 
    self._waitTriggerTime = 0        
    self._isTriggerClick = false
    self._randEventTimeDown = 0 

    --移动事件用的
    self._targetPosId = 0     
    self._curMoveDis = 0       
    self._maxMoveDis = 0       
    self._moveSpeed = 0        
    self._wayCinemachineSmoothPath = nil  
    self._curMoveStatus = 0  

    self._curTLTime = 0
    self._curMarkerTimeInfo = {} --当前的marker点信息
end

function RoleInstance:IsCanRandEvent()
    return self._randEventTimeDown <= 0
end

--点击人物
function RoleInstance:OnClick()
    if self._curRoleStatus == RoleStatus.None or self._curRoleStatus == RoleStatus.InitEvent then
        return
    elseif checkNumber(KCookie.Get("MainHomeRoleEventPlay")) == 1 then    --事件播放中 
        return
    elseif checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 then
        return
    --如果已经打开了ui界面  发个事件退出
    elseif checkNumber(KCookie.Get(Constants.IsBeginInteractive)) == 1 then
        Events.Broadcast(Constants.EventNames.ClickMainHomeRole)
        return
    end

    if GuideUtils.IsInGuiding() then
        if checkNumber(self._roleId) == GuideRoleId then
            if KCookie.Get("QTEEnd") == 1 or self:IsOpenSpecifyGuide() then return end
            if self.__animatorResetComplete == nil then
                self.__animatorResetComplete = Events.AddListener(Constants.EventNames.MainHomeCameraAnimatorResetComplete, function()
                    if GuideUtils.IsInGuiding() then
                        GuideUtils.ShowGuideModuleTips()
                        UIRaycastBlocker:RemoveCondition(Constants.EventNames.MainHomeCameraAnimatorResetComplete)
                    end
                end)
            end
            UIRaycastBlocker:AddCondition(Constants.EventNames.MainHomeCameraAnimatorResetComplete)
            Events.Broadcast(Constants.EventNames.MainHomeCameraAnimatorReset)
            --GuideUtils.ShowGuideModuleTips()
        end
        return

    end

    --不在事件播放中 不能点击
    if self._curRoleStatus ~= RoleStatus.EventPlaying then
        return
    end
    --主界面不显示不让点
    if checkNumber(KCookie.Get("IsInUIHomeMain")) ~= 1 then
        return
    end

    --栈顶不是主界面
    local topDialog = UIModule.CurrentScreen:LastDialog()
    if topDialog.Argument.id ~= Constants.UITypeIds.UIHomeView then
        return
    end

    local eventType = checkNumber(self._curEventVo.type)
    if eventType == RoleEventType.UIClick then
        self:OnUIClickAction()
    elseif eventType == RoleEventType.TLClick then
        if not self._isTriggerClick then
            --点击秒切动作  子男说的
            self._isTriggerClick = true
            if not isNull(self._triggerCam) then
                CfUtils.SetActive(self._triggerCam, true)
            end
            self:SetCurTimeLineStatus(TimeLineStatus.Trigger)
        end
    elseif eventType == RoleEventType.StoryClick or eventType == RoleEventType.Login then
        if not self._isTriggerClick then
            Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, { isTrue = false })
            KCookie.Set(Constants.IsOpnePageing, 1)
            UIRaycastBlocker:AddCondition("OpenDialogAction")
            cs_coroutine.start(function()
                xTry(function()
                    KCookie.Set("MainHomeRoleEventPlay", 1)
                    --CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("ClickMainHomeRole")
                    CfUtils.ChangeMainCamDefalultBlend(0)
        
                    --点击秒切动作  子男说的
                    self._isTriggerClick = true
                    if not isNull(self._triggerCam) then
                        CfUtils.SetActive(self._triggerCam, true)
                    end
        
                    self:SetCurTimeLineStatus(TimeLineStatus.Trigger)
                    Events.Broadcast('AllMainUI', false)
                    Events.Broadcast(Constants.EventNames.MainHomeScrollActive, {isTrue = false})
                    self._roleTalkGo = self:GetRoleTalkGo()
                    if not isNull(self._roleTalkGo) then
                        local scr = CfUtils.GetLuaScr(self._roleTalkGo, "Game.UI.MainInteraction.UIRoleEventTalkNode")
                        if scr then
                            scr:Refresh(self._roleId, self._curEventVo.id)
                        end
                    end
        
                    --有语音
                    if checkString(self._curEventVo.voiceId) ~= "" then
                        CriWareUtils.PlayVoiceById(self._curEventVo.voiceId, self._modelGo)
                    end
        
                    coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainInteractionSkipDialog, parameters = {cb = function()
                        self:SetCurTimeLineMarkerStatus(MarkerKey.HomeRoleEnd)
                    end}}, {
                    }))
                    UIRaycastBlocker:RemoveCondition("OpenDialogAction")
                    --KCookie.Set(Constants.IsOpnePageing, 0)
                end, function()
                    UIRaycastBlocker:RemoveCondition("OpenDialogAction")
                    KCookie.Set(Constants.IsOpnePageing, 0)
                end)
            end)
        end
    elseif eventType == RoleEventType.RoleLeave then
    else
        self._isTriggerClick = true
    end
end

--获取说话的预设
function RoleInstance:GetRoleTalkGo()
    if isNull(self._roleTalkGoLoader) then
        self._roleTalkGoLoader = ResourceModule.LoadBundleSync("Prefabs/MainInteraction/UIRoleEventTalkNode.prefab")
    end
    if isNull(self._roleTalkGoLoader) then
        return nil
    end
    local go = CfUtils.InstantiateGo(self._roleTalkGoLoader.ResultObject.gameObject, UIModule.RootCanvas.gameObject)
    return go
end

--播放当前的timeline
function RoleInstance:PlayTimeLine()
    if not self._curTLInfo then
        return
    elseif isNull(self._curTLInfo.go) then
        return
    end
    KTool.SetActive(self._curTLInfo.go, true)

    local pd = KTool.GetComponent(self._curTLInfo.go, typeof(CS.UnityEngine.Playables.PlayableDirector))
    if pd then
        pd:Pause()
        if self._curTLTime > 0 then
            pd.time = self._curTLTime
            self._curTLTime = 0
        end
        pd:Play()
    end
end

--暂停当前的timeline
function RoleInstance:PauseTimeLine()
    if not self._curTLInfo then
        return
    elseif isNull(self._curTLInfo.go) then
        return
    end
    KTool.SetActive(self._curTLInfo.go, false)

    local pd = KTool.GetComponent(self._curTLInfo.go, typeof(CS.UnityEngine.Playables.PlayableDirector))
    if pd then
        pd:Pause()
        --有值的时候就不存了 防止多个事件
        if self._curTLTime <= 0 then
            self._curTLTime = pd.time
        end
    end
end

--获取一个角色事件
function RoleInstance:GetRoleEventVo(id)
    id = checkNumber(id)
    if id <= 0 then
        return nil
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1811, "RoleEventVo", id)
    --vo.type = 8
    --vo.bubbleBox = 1
    return vo
end

--设置一个缓存事件
function RoleInstance:SetBuffEventId(eventId)
    self._bufferEventId = eventId
end

function RoleInstance:GetBuffEventId()
    local id = self._bufferEventId
    self._bufferEventId = nil
    return id
end 


