---OnUIClickAction
---点击UI事件 warn:引导也会调用
function RoleInstance:OnUIClickAction()
    KCookie.Set(Constants.IsOpnePageing, 1)
    UIRaycastBlocker:AddCondition("OpenDialogAction")
    cs_coroutine.start(function()
        xTry(function()
            Events.Broadcast(Constants.EventNames.MainHomeRoleActivity, { isActivity = false})

            Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, {isTrue = false})
            KCookie.Set(Constants.IsBeginInteractive, 1)
            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = false, roleId = self._roleId})
            CS.UINavigationBarRoot.Instance:SetActive(false)
            Events.Broadcast('AllMainUI', false)
            coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainInteractionDialog, parameters = {roleId = self._roleId, posId = self._posId}}, {
                {id = Constants.UITypeIds.UIHomeView}
            }))
            UIRaycastBlocker:RemoveCondition("OpenDialogAction")
            KCookie.Set(Constants.IsOpnePageing, 0)
            RoleVoiceMgr:GetInstance():PlayHomeTouchVoiceByRoleId(self._roleId)
        end, function()
            UIRaycastBlocker:RemoveCondition("OpenDialogAction")
            KCookie.Set(Constants.IsOpnePageing, 0)
        end)
    end)
end

---Clear
function RoleInstance:Clear()
    if not isNull(self._parGo) then
        CfUtils.SetActive(self._parGo, false)
    end

    if not isNull(self._roleTalkGo) then
        GameObject.Destroy(self._roleTalkGo)
        if not isNull(self._roleTalkGoLoader) then
            self._roleTalkGoLoader:Release(true)
            self._roleTalkGoLoader = nil
        end
    end
    self:ClearEventInfo(true)
    if not isNull(self._modelGo) then
        self._roleShowMgr:PushModelGo(self._modelGo, self._roleId)
        --GameObject.Destroy(self._modelGo)
    end
    self:Delete() --清除资源
end

return RoleInstance